/// The catalogue source a transform's events are stamped with.
#[must_use]
pub fn label(variant: &str) -> Option<&'static str> {
    LABELS
        .binary_search_by_key(&variant, |&(v, _)| v)
        .ok()
        .map(|i| LABELS[i].1)
}
